import { createFileRoute, Link } from '@tanstack/react-router'
import { createServerFn } from '@tanstack/start'
import Database from 'better-sqlite3'

const getPosts = createServerFn({
  method: 'GET',
}).handler(async () => {
  const db = new Database('/home/user/blog/blog.db')
  const posts = db.prepare('SELECT id, title FROM posts').all()
  return posts as { id: number; title: string }[]
})

export const Route = createFileRoute('/')({
  loader: async () => await getPosts(),
  component: Index,
})

function Index() {
  const posts = Route.useLoaderData()

  return (
    <div>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link to={`/posts/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>
    </div>
  )
}

import { createFileRoute, Link } from '@tanstack/react-router'
import { createServerFn } from '@tanstack/start'
import Database from 'better-sqlite3'
import { marked } from 'marked'

const getPost = createServerFn({
  method: 'GET',
})
  .validator((data: number) => data)
  .handler(async ({ data: postId }) => {
    const db = new Database('/home/user/blog/blog.db')
    const post = db.prepare('SELECT id, title, content FROM posts WHERE id = ?').get(postId) as { id: number; title: string; content: string } | undefined
    if (!post) {
      throw new Error('Post not found')
    }
    const htmlContent = marked.parse(post.content)
    return { ...post, htmlContent }
  })

export const Route = createFileRoute('/posts/$postId')({
  loader: async ({ params }) => await getPost({ data: Number(params.postId) }),
  component: Post,
})

function Post() {
  const post = Route.useLoaderData()

  return (
    <div>
      <Link to="/">Back to Home</Link>
      <h1>{post.title}</h1>
      <div dangerouslySetInnerHTML={{ __html: post.htmlContent }} />
    </div>
  )
}

